def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    if not target_concurrency:
        target_concurrency = 1
    if len(varargs) == 0:
        return (0, b'')
    partitions = get_partitions(varargs, target_concurrency)
    pool = ThreadPool(target_concurrency)
    results = []
    for partition in partitions:
        results.append(pool.apply_async(_run_command, (cmd, partition)))
    pool.close()
    pool.join()
    status = 0
    output = b''
    for result in results:
        res, out = result.get()
        status = res or status
        output += out
    return (status, output)

