def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    _cache = {}
    _lock = threading.Lock()
    _hit_count = 0
    _miss_count = 0

    def _wrapper(func):
        _cached_func = lru_cache(maxsize, typed)(func)
        def _memoized_func(*args, **kwargs):
            key = _cached_func.make_key(args, kwargs)
            _lock.acquire()
            try:
                result = _cache.get(key, None)
                if result is None:
                    result = _cached_func(*args, **kwargs)
                    _cache[key] = result
                    _hit_count += 1
                elif timer() - _cache[key][2] > ttl:
                    _miss_count += 1
                    result = _cached_func(*args, **kwargs)
                    _cache[key] = result
                else:
                    _miss_count += 1
            finally:
                _lock.release()
            return result
        return _memoized_func

    def _clear_cache():
        nonlocal _cache
        _cache.clear()

    def _cache_info():
        return _hit_count, _miss_count, len(self.__cache))

    return _wrapper

def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        args = []
        vals = []

        def wrapper(*args, **kwargs):
            if args in cache:
                return cache[args]
            else:
                result = func(*args, **kwargs)
                cache[args] = result
                args.append(args)
                vals.append(result)
                if len(cache) > maxsize:
                    cache.pop(args[0])
                    vals.pop(0)
                return result

        return wrapper

    return decorator

