        return False

    # Check if the type value is valid
    if inventory['type'] not in self.valid_types:
        return False

    # If extract_spec_version is True, look at the type value to determine the specification version
    if extract_spec_version:
        spec_version = self.get_spec_version(inventory['type'])
        if spec_version != self.spec_version:
            return False

    # Check if the inventory has the required fields for the current specification version
    required_fields = self.get_required_fields(spec_version)
    for field in required_fields:
        if field not in inventory:
            return False

    # Check if the inventory has the correct format for the current specification version
    field_format = self.get_field_format(spec_version)
    for field, format in field_format.items():
        if not isinstance(inventory[field], format):
            return False

    return True

