def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    parts = frequency.strip().split(" ")
    if len(parts) != 2:
        raise ValueError("Invalid frequency: {}".format(frequency))

    try:
        number = int(parts[0])
        unit = parts[1].lower()
    except ValueError:
        raise ValueError("Invalid frequency: {}".format(frequency))

    if unit == "week":
        unit = "weeks"
    elif unit == "day":
        unit = "days"
    elif unit == "hour":
        unit = "hours"
    elif unit == "minute":
        unit = "minutes"
    elif unit == "second":
        unit = "seconds"
    else:
        raise ValueError("Invalid frequency unit: {}".format(unit))

    return datetime.timedelta(**{unit: number})

