    # Making sure the candidate claims that it provides the interface using `iface.providedBy`
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid('Candidate does not provide {0}'.format(iface))

    # Making sure the candidate defines all the necessary methods
    for name, method in iface.namesAndDescriptions():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid(
                'Candidate does not define {0} method'.format(name))
        # Making sure the methods have the correct signature
        if inspect.getfullargspec(method) != inspect.getfullargspec(getattr(candidate, name)):
            raise zope.interface.Invalid(
                'Method signature for {0} does not match'.format(name))

    # Making sure the candidate defines all the necessary attributes
    for name, attr in iface.attributes:
        if not hasattr(candidate, name):
            raise zope.interface.Invalid('Candidate does not define {0} attribute'.format(name))

    return True

