def popitem(self):
    """Remove and return the (key, value) pair least frequently used."""
    if not self._items:
        raise KeyError("popitem(): cached item dict is empty")
    min_freq = min(self._items.values())
    min_key = None
    for key, freq in self._items.items():
        if freq == min_freq:
            min_key = key
            break
    if min_key is None:
        raise KeyError("popitem(): minimum frequency not found")
    value = self._items.pop(min_key)
    return min_key, value

